const html: string = "<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>견적서 작성</title>\n<script>try { if(!localStorage.getItem(\"jooyong-token\")) document.documentElement.classList.add(\"locked\"); } catch(e){}</script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Nanum+Gothic:wght@400;700;800&family=Nanum+Myeongjo:wght@700;800&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\n<style>\n:root{--bg:#f3f4f1;--card:#fff;--ink:#1d211c;--muted:#6b7068;--line:#d9dcd5;--accent:#2f6b3a;--accent-ink:#fff;--danger:#b3261e}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:\"Nanum Gothic\",system-ui,sans-serif;font-size:15px}\nheader.top{background:var(--accent);color:#fff;padding:12px 16px;display:flex;align-items:center;justify-content:space-between;gap:8px;position:sticky;top:0;z-index:5}\nheader.top h1{font-size:17px;margin:0}\n.wrap{max-width:1100px;margin:0 auto;padding:16px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px;margin-bottom:14px}\n.card h2{font-size:15px;margin:0 0 10px;display:flex;justify-content:space-between;align-items:center}\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\nlabel{display:block;font-size:12px;color:var(--muted);margin-bottom:3px}\ninput,select{width:100%;padding:9px 10px;border:1px solid var(--line);border-radius:7px;font:inherit;background:#fff;color:var(--ink)}\ninput:focus,select:focus{outline:2px solid var(--accent);border-color:transparent}\nbutton{font:inherit;border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:7px;padding:8px 12px;cursor:pointer}\nbutton.primary{background:var(--accent);color:var(--accent-ink);border-color:var(--accent);font-weight:700}\nbutton.ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.5)}\nbutton.del{color:var(--danger);padding:6px 9px}\ndetails summary{cursor:pointer;font-weight:700;font-size:15px}\n.items{display:flex;flex-direction:column;gap:8px}\n.item{display:grid;grid-template-columns:2fr 1.5fr .8fr .8fr 1.2fr 1.2fr 1fr auto;gap:6px;align-items:center}\n.item .amt{text-align:right;font-weight:700;font-size:14px}\n.item.blank{opacity:.55}\n.item-head{font-size:12px;color:var(--muted)}\n.row-btns{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n.totals{display:flex;gap:16px;flex-wrap:wrap;margin-top:12px;font-size:14px}\n.totals b{font-size:16px}\n.dl{display:flex;gap:8px;flex-wrap:wrap}\n.dl button{flex:1;min-width:90px;padding:12px}\n.preview-scroll{overflow-x:auto;background:#888;border-radius:10px;padding:16px}\n@media (max-width:760px){\n  .item{grid-template-columns:1fr 1fr 1fr;background:#fafbf8;border:1px solid var(--line);border-radius:8px;padding:8px}\n  .item .nm{grid-column:1/3}.item .del{grid-column:3;justify-self:end}\n  .item .amt{grid-column:1/4}\n  .item-head{display:none}\n}\n/* ===== 견적서 양식 ===== */\n#sheet{width:760px;margin:0 auto;background:#fff;color:#000;padding:26px 24px 30px;font-family:\"Nanum Gothic\",sans-serif;font-size:12.5px}\n#sheet .ttl{text-align:center;font-family:\"Nanum Myeongjo\",serif;font-size:28px;font-weight:800;letter-spacing:14px;margin:0 0 26px}\n#sheet .hdr{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:8px}\n#sheet .client{font-size:16px;font-weight:700;border-bottom:1.5px solid #000;min-width:300px;display:flex;justify-content:space-between;padding:0 4px 2px}\n#sheet .co{text-align:right}\n#sheet .co .nm{font-size:22px;font-weight:800;margin-bottom:6px}\n#sheet .co .ad{font-size:12px;margin-bottom:4px}\n#sheet .co .tel{color:#1a35c9;text-decoration:underline;font-size:13px}\n#sheet .info{width:100%;border-collapse:collapse;margin-bottom:22px}\n#sheet .info td{padding:3px 4px;font-size:14px;font-weight:700;border-bottom:1px solid #000;vertical-align:middle}\n#sheet .info td.k{width:90px;letter-spacing:8px}\n#sheet .info td.c{width:18px;text-align:center}\n#sheet .info td.nb{border-bottom:none}\n#sheet .info .vat{color:#d00}\n#sheet .stamp{display:inline-block;width:56px;height:56px;vertical-align:middle;margin-left:4px} /* A4 기준 약 15mm */\n#sheet .stamp img,#sheet .stamp svg{width:100%;height:100%;object-fit:contain}\n#sheet table.it{width:100%;border-collapse:collapse;border:2px solid #000}\n#sheet table.it th,#sheet table.it td{border:1px solid #777;padding:3px 6px;height:23px;font-size:12px}\n#sheet table.it thead th{background:var(--head,#d6ead2);font-weight:700;text-align:center;border-color:#000}\n#sheet table.it td.n{text-align:right}\n#sheet table.it td.ctr{text-align:center}\n#sheet table.it tr.sum td{background:var(--sum,#d9d9d9);font-weight:700;font-size:13px}\n#sheet table.it tr.sum.total td{border-top:2px solid #000}\n#sheet table.it tr.foot td{background:#fff;font-weight:400}\n.tabs{display:flex;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:50px;z-index:4}\n.tabs button{flex:1;border:none;border-radius:0;padding:13px;font-weight:700;color:var(--muted);background:#fff;border-bottom:3px solid transparent}\n.tabs button.on{color:var(--accent);border-bottom-color:var(--accent)}\n.tabs span{font-size:12px;background:#eef5ee;color:var(--accent);border-radius:10px;padding:1px 7px;margin-left:4px}\n.save{width:100%;padding:13px;margin-bottom:8px;background:#1d211c;border-color:#1d211c}\n.editing{display:none;background:#fff7e0;border:1px solid #f0d58a;border-radius:8px;padding:10px 14px;margin-bottom:14px;font-size:13px}\n.editing.show{display:block}\n.chk{display:flex;align-items:center;gap:6px;margin-top:8px;font-size:13px;color:var(--ink);cursor:pointer}\n.chk input{width:auto;margin:0}\n.save-state.dirty{color:#b26a00}\n.save-state{font-size:12.5px;color:var(--accent);text-align:center;margin:-2px 0 10px}\n.qrow .t small.dates{display:block;color:#8a8f86;font-size:11.5px;margin-top:2px}\n.list-sum{font-size:13px;color:var(--muted);margin:10px 2px}\n.qrow{display:grid;grid-template-columns:118px 1fr auto auto;gap:12px;align-items:center;padding:12px 4px;border-top:1px solid var(--line)}\n.qrow .d{font-size:12.5px;color:var(--muted);white-space:nowrap}\n.qrow .t b{display:block;font-size:15px}.qrow .t small{color:var(--muted);font-size:12px}\n.qrow .m{font-weight:800;text-align:right;white-space:nowrap}\n.qrow .a{display:flex;gap:4px}.qrow .a button{padding:6px 9px;font-size:13px}\n.empty{text-align:center;color:var(--muted);padding:40px 0}\n@media (max-width:640px){.qrow{grid-template-columns:1fr auto}.qrow .d{grid-column:1/-1}.qrow .a{grid-column:1/-1;justify-content:flex-end}}\n.hdr-r{display:flex;align-items:center;gap:6px}\n#syncState{font-size:11.5px;opacity:.8;white-space:nowrap}\n#btnLogout{font-size:12px;padding:6px 9px}\n#login{position:fixed;inset:0;background:linear-gradient(160deg,#2f6b3a,#1d3a22);z-index:100;display:flex;align-items:center;justify-content:center;padding:16px}\n#login[hidden]{display:none}\nhtml.locked #login{display:flex}\nhtml.locked, html.locked body{overflow:hidden}\nhtml.locked body > :not(#login){visibility:hidden}\n.login-card{background:#fff;border-radius:14px;padding:24px;width:100%;max-width:360px;display:flex;flex-direction:column;gap:12px}\n.login-card h2{margin:0;font-size:19px}\n.login-card p{margin:0;font-size:13px;color:var(--muted);line-height:1.6}\n.login-card button{padding:12px}\n#loginMsg{color:var(--danger);font-size:13px;min-height:1em}\n@media (max-width:480px){#syncState{display:none}}\n.co-pick{display:flex;gap:8px;align-items:flex-end;margin-top:12px;flex-wrap:wrap}\n.co-pick button{white-space:nowrap}\n.co-now{font-weight:400;color:var(--muted);font-size:13px}\n.hint{font-size:12px;color:var(--muted);margin:0 0 10px}\nbutton.mini{font-size:12px;padding:5px 10px;font-weight:700}\n.fld{position:relative;min-width:0}\n.fld input{width:100%}\n#ac{position:absolute;z-index:50;background:#fff;border:1px solid var(--line);border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,.15);max-height:300px;overflow:auto;max-width:calc(100vw - 16px);padding-bottom:4px}\n#ac .ac-h{position:sticky;top:0;background:#f6f7f4;font-size:11.5px;color:var(--muted);padding:7px 10px;display:flex;justify-content:space-between;align-items:center;gap:8px}\n#ac .ac-h button{font-size:11px;padding:3px 8px}\n#ac .ac-o{padding:10px 12px;cursor:pointer;font-size:14.5px;display:flex;justify-content:space-between;gap:12px}\n#ac .ac-o small{color:var(--muted);font-size:12px;white-space:nowrap}\n#ac .ac-o:hover,#ac .ac-o.on{background:#eef5ee}\n#ac .ac-o.cur{font-weight:800;color:var(--accent)}\n#ac .ac-o.add{color:var(--accent);font-weight:700;border-top:1px solid var(--line)}\n.lib-tabs{display:flex;gap:6px}\n.lib-tabs button{flex:1;font-weight:700}.lib-tabs button.on{background:var(--accent);color:#fff;border-color:var(--accent)}\n.lib-add{display:flex;gap:6px;margin:10px 0 8px}.lib-add button{white-space:nowrap}\n.lib-rows{display:flex;flex-direction:column;max-height:380px;overflow:auto;border:1px solid var(--line);border-radius:8px}\n.lib-row{display:grid;grid-template-columns:1fr 80px 120px auto;gap:6px;align-items:center;padding:6px 8px;border-bottom:1px solid #eee}\n.lib-row span{font-weight:700}.lib-row input{padding:6px 8px}\n.lib-chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{display:inline-flex;align-items:center;gap:4px;background:#eef5ee;border-radius:16px;padding:5px 6px 5px 12px;font-weight:700;font-size:14px}\n.chip button{border:none;background:none;color:var(--danger);padding:0 4px}\n@media (max-width:760px){\n  .fld::before{content:attr(data-l);display:block;font-size:10.5px;color:var(--muted);margin:0 0 2px 2px}\n  .lib-row{grid-template-columns:1fr 64px 96px auto}\n}\ninput[type=color]{height:42px;padding:3px;cursor:pointer}\n.swatches{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;align-items:center;font-size:12px;color:var(--muted)}\n.swatches button{width:30px;height:30px;border-radius:50%;padding:0;border:2px solid #fff;box-shadow:0 0 0 1px var(--line)}\n#sheet .note{margin-top:14px;font-size:11.5px;color:#555;border-top:1px solid #ddd;padding-top:8px;white-space:pre-wrap}\n.tpl{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.tpl button{padding:12px 6px;font-weight:700;display:flex;flex-direction:column;gap:3px;align-items:center}\n.tpl button small{font-weight:400;font-size:11px;color:var(--muted)}\n.tpl button.on{border:2px solid var(--accent);background:#eef5ee}\n/* ===== 모던형 / 조경형 ===== */\n#sheet table.it tr.sum.total td{background:var(--total,#bfbfbf)}\n#sheet.mx{padding:0;font-size:12.5px;color:#222}\n#sheet.mx .stamp{display:inline-block;width:62px;height:62px}\n#sheet.mx .stamp img,#sheet.mx .stamp svg{width:100%;height:100%;object-fit:contain}\n.mx .n{text-align:right;font-variant-numeric:tabular-nums}.mx .c{text-align:center}\n.mx table{width:100%;border-collapse:collapse}\n\n/* 모던형: 진한 상단 띠 + 정보 카드 */\n.modern .m-band{background:var(--dark,#24292e);color:#fff;padding:30px 40px 26px;display:flex;justify-content:space-between;align-items:flex-end}\n.modern .m-co{font-size:24px;font-weight:800;letter-spacing:1px}\n.modern .m-sub{font-size:11px;color:#b9c0c7;margin-top:8px;line-height:1.7}\n.modern .m-doc{text-align:right;font-size:30px;font-weight:800;letter-spacing:8px;line-height:1}\n.modern .m-doc span{display:block;font-size:10.5px;letter-spacing:5px;color:var(--main,#3f9a68);margin-top:8px;font-weight:700}\n.modern .m-accent{height:5px;background:var(--main,#3f9a68)}\n.modern .m-body{padding:26px 40px 34px}\n.modern .m-cards{display:grid;grid-template-columns:1.1fr 1fr 1.15fr 1.3fr;white-space:nowrap;border:1px solid #dcdfe2;border-radius:8px;overflow:hidden}\n.modern .m-cards>div{padding:12px 14px;border-right:1px solid #dcdfe2}\n.modern .m-cards>div:last-child{border:none;background:var(--light,#f0f7f2)}\n.modern .m-cards label{display:block;font-size:10.5px;color:#888;margin-bottom:6px;letter-spacing:1px}\n.modern .m-cards b{font-size:14px}\n.modern .m-cards .hl b{font-size:18px;color:var(--main,#3f9a68)}\n.modern .m-kor{font-size:12px;color:#555;margin:10px 2px 22px;text-align:right}\n.modern thead th{background:#f3f4f5;color:#555;font-size:11px;font-weight:700;padding:10px 8px;text-align:left;letter-spacing:.5px}\n.modern thead th:first-child{border-radius:6px 0 0 6px}.modern thead th:last-child{border-radius:0 6px 6px 0}\n.modern tbody td{padding:9px 8px;border-bottom:1px solid #eceef0}\n.modern tbody tr.gap td{border:none;padding:5px}\n.modern .no{color:#aaa;font-size:11px;width:28px}\n.modern .m-bottom{display:flex;justify-content:space-between;gap:24px;margin-top:22px;align-items:flex-start}\n.modern .m-bank{font-size:12px;color:#555;line-height:1.8;background:#f7f8f9;border-radius:8px;padding:12px 16px;flex:1}\n.modern .m-bank b{color:#222}\n.modern .m-sum{width:290px}\n.modern .m-sum div{display:flex;justify-content:space-between;padding:7px 12px;font-size:13px}\n.modern .m-sum .g{background:var(--dark,#24292e);color:#fff;border-radius:6px;font-size:16px;font-weight:800;padding:12px;margin-top:6px}\n.modern .m-sign{margin-top:30px;text-align:right;font-size:13px;color:#444;display:flex;justify-content:flex-end;align-items:center;gap:10px}\n.modern .m-sign b{font-size:15px;color:#222}\n\n/* 조경형: 미색 종이 + 숲색 + 식물 장식 */\n#sheet.garden{background:#fff;color:#26332a;font-family:\"Nanum Myeongjo\",serif}\n.garden .g-wrap{padding:34px 44px 36px;position:relative;overflow:hidden}\n.garden .g-branch{position:absolute;left:-10px;top:-6px;width:170px;opacity:.9}\n.garden .g-branch2{position:absolute;right:-20px;bottom:-14px;width:150px;opacity:.35;transform:rotate(180deg)}\n.garden .g-title{text-align:center;margin:8px 0 26px}\n.garden .g-title b{font-size:32px;letter-spacing:16px;color:var(--main,#1f4d2e);font-weight:800}\n.garden .g-title span{display:block;font-family:\"Nanum Gothic\",sans-serif;font-size:10px;letter-spacing:6px;color:#8aa58c;margin-top:6px}\n.garden .g-row{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:18px}\n.garden .g-to{font-size:13px;line-height:2}\n.garden .g-to .who{font-size:19px;font-weight:800;border-bottom:1px solid var(--main,#1f4d2e);padding-right:30px;display:inline-block;line-height:1.6}\n.garden .g-to small{font-family:\"Nanum Gothic\",sans-serif;color:#7d8b80;font-size:11px;display:inline-block;width:52px}\n.garden .g-co{text-align:right;font-family:\"Nanum Gothic\",sans-serif;font-size:11px;color:#5b6a5f;line-height:1.7}\n.garden .g-co .nm{font-family:\"Nanum Myeongjo\",serif;font-size:22px;font-weight:800;color:var(--main,#1f4d2e);display:flex;align-items:center;justify-content:flex-end;gap:2px}\n.garden .g-co .nm small{font-family:\"Nanum Gothic\",sans-serif;font-size:11px;color:#5b6a5f;font-weight:400;margin:0 4px 0 10px}\n.garden .g-amt{border-top:3px double var(--main,#1f4d2e);border-bottom:3px double var(--main,#1f4d2e);padding:12px 6px;display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}\n.garden .g-amt .k{font-size:14px;font-weight:700}\n.garden .g-amt .v{font-size:22px;font-weight:800;color:var(--main,#1f4d2e)}\n.garden .g-amt .v small{font-family:\"Nanum Gothic\",sans-serif;font-size:10.5px;color:#a0522d;font-weight:400;margin-left:6px}\n.garden table{font-family:\"Nanum Gothic\",sans-serif}\n.garden thead th{font-size:11px;color:var(--main,#1f4d2e);font-weight:800;padding:8px 6px;border-bottom:2px solid var(--main,#1f4d2e);text-align:left;letter-spacing:1px}\n.garden tbody td{padding:8px 6px;border-bottom:1px dotted #b7c7b8;font-size:12.5px}\n.garden tbody tr.gap td{border:none;padding:2px;text-align:center;color:#8aa58c;font-size:10px;letter-spacing:6px}\n.garden .g-tot{display:flex;justify-content:space-between;align-items:flex-end;margin-top:18px;font-family:\"Nanum Gothic\",sans-serif}\n.garden .g-bank{font-size:11.5px;color:#5b6a5f;line-height:1.8}\n.garden .g-bank b{color:#26332a}\n.garden .g-sum{width:280px;font-size:12.5px}\n.garden .g-sum div{display:flex;justify-content:space-between;padding:5px 14px}\n.garden .g-sum .g{background:var(--main,#1f4d2e);color:#fbf8f0;border-radius:30px;font-size:15px;font-weight:800;padding:10px 18px;margin-top:6px}\n.garden .g-foot{text-align:center;margin-top:26px;font-size:12px;color:#5b6a5f}\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <h1>미래조경 견적</h1>\n  <div class=\"hdr-r\"><span id=\"syncState\"></span><button class=\"ghost\" id=\"btnNew\">＋ 새 견적</button><button class=\"ghost\" id=\"btnLogout\" title=\"로그아웃\">로그아웃</button></div>\n</header>\n<div id=\"login\" hidden>\n  <form id=\"loginForm\" class=\"login-card\">\n    <h2>견적서 로그인</h2>\n    <p>핸드폰과 PC에서 같은 견적 리스트를 쓰려면 비밀번호를 입력하세요. 한 번 로그인하면 이 기기에서는 180일 동안 유지돼요.</p>\n    <input type=\"password\" id=\"loginPw\" placeholder=\"비밀번호\" autocomplete=\"current-password\" required>\n    <button class=\"primary\" type=\"submit\">로그인</button>\n    <div id=\"loginMsg\"></div>\n  </form>\n</div>\n<nav class=\"tabs\">\n  <button data-page=\"edit\" class=\"on\">견적서 작성</button>\n  <button data-page=\"list\">발급 리스트 <span id=\"listCount\"></span></button>\n</nav>\n\n<div class=\"wrap\" id=\"pageList\" hidden>\n  <div class=\"card\">\n    <input id=\"search\" placeholder=\"받는 분 · 공사명 · 공종명 검색\">\n    <div class=\"list-sum\" id=\"listSum\"></div>\n    <div id=\"list\"></div>\n  </div>\n</div>\n\n<div class=\"wrap\" id=\"pageEdit\">\n  <div class=\"editing\" id=\"editing\"></div>\n  <details class=\"card\" id=\"coBox\">\n    <summary>회사 정보 <span id=\"coNow\" class=\"co-now\"></span></summary>\n    <div class=\"co-pick\">\n      <div style=\"flex:1;min-width:180px\"><label>저장된 회사 정보 불러오기</label><select id=\"coSel\"></select></div>\n      <button id=\"coAdd\">＋ 새 회사 추가</button>\n      <button class=\"del\" id=\"coDel\">삭제</button>\n    </div>\n    <p class=\"hint\" style=\"margin-top:8px\">아래 내용을 고치면 선택된 회사 정보에 바로 저장돼요. 견적서마다 어떤 회사로 발급했는지도 함께 기억해요.</p>\n    <div class=\"grid\" style=\"margin-top:12px\">\n      <div><label>상호</label><input data-co=\"name\"></div>\n      <div><label>대표자</label><input data-co=\"ceo\"></div>\n      <div style=\"grid-column:span 2\"><label>주소</label><input data-co=\"addr\"></div>\n      <div><label>전화</label><input data-co=\"tel\"></div>\n      <div><label>팩스</label><input data-co=\"fax\"></div>\n      <div><label>담당자 연락처</label><input data-co=\"phone\"></div>\n      <div><label>입금 은행</label><input data-co=\"bank\"></div>\n      <div><label>예금주</label><input data-co=\"holder\"></div>\n      <div><label>계좌번호</label><input data-co=\"account\"></div>\n      <div><label>다른 도장 이미지로 바꾸기 (자동으로 잘라줌)</label><input type=\"file\" accept=\"image/*\" id=\"stampFile\"></div>\n      <div style=\"display:flex;align-items:flex-end\"><button id=\"stampClear\">기본 도장으로 되돌리기</button></div>\n    </div>\n  </details>\n\n  <div class=\"card\">\n    <h2>기본 정보</h2>\n    <div class=\"grid\">\n      <div><label>받는 분 (귀하)</label><input data-q=\"client\" placeholder=\"예: 송정동\"></div>\n      <div><label>일자</label><input type=\"date\" data-q=\"date\"></div>\n      <div><label>공사명</label><input data-q=\"title\" placeholder=\"예: 전원주택\"></div>\n      <div><label>공과잡비 (%)</label><input data-q=\"rate\" inputmode=\"decimal\"></div>\n      <div><label>부가세</label><select data-q=\"vat\"><option>부가세별도</option><option>부가세포함</option></select>\n        <label class=\"chk\" id=\"vatShowBox\"><input type=\"checkbox\" id=\"vatShow\"> <span id=\"vatShowTxt\">견적서에 부가세 표시</span></label></div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>공종 내역 <button class=\"mini\" onclick=\"openLib('n')\">자주 쓰는 항목 관리</button></h2>\n    <p class=\"hint\">한 글자만 쳐도 추천이 떠요 (초성 ‘ㅅㄴ’ → 소나무). 목록에 없는 말도 자유롭게 입력할 수 있어요.</p>\n    <div class=\"item item-head\"><span>공종명</span><span>규격</span><span>단위</span><span>수량</span><span>단가</span><span>비고</span><span style=\"text-align:right\">금액</span><span></span></div>\n    <div class=\"items\" id=\"items\"></div>\n    <div class=\"row-btns\">\n      <button class=\"primary\" id=\"addItem\">＋ 항목 추가</button>\n      <button id=\"addBlank\">빈 줄 추가 (구분용)</button>\n    </div>\n    <div class=\"totals\">\n      <span>계 <b id=\"tSub\">0</b></span>\n      <span>공과잡비 <b id=\"tEtc\">0</b></span>\n      <span>합계 <b id=\"tTot\">0</b></span>\n      <span id=\"tVatWrap\">부가세 <b id=\"tVat\">0</b></span>\n      <span>총액(부가세 포함) <b id=\"tGrand\">0</b></span>\n    </div>\n  </div>\n\n  <details class=\"card\" id=\"libBox\">\n    <summary>자주 쓰는 항목 관리</summary>\n    <div class=\"lib-tabs\" id=\"libTabs\" style=\"margin-top:12px\">\n      <button data-libtab=\"n\" class=\"on\">공종명</button><button data-libtab=\"s\">규격</button><button data-libtab=\"u\">단위</button>\n    </div>\n    <div class=\"lib-add\"><input id=\"libAdd\"><button class=\"primary\" id=\"libAddBtn\">추가</button></div>\n    <p class=\"hint\">공종명에 기본 단가·단위를 넣어두면 견적 작성 때 자동으로 채워져요. 견적에 새로 입력한 말도 자동으로 여기에 쌓여요.</p>\n    <div id=\"libList\"></div>\n    <div class=\"row-btns\"><button id=\"libReset\">이 목록 처음 상태로</button></div>\n  </details>\n\n  <div class=\"card\">\n    <h2>양식 선택</h2>\n    <div class=\"tpl\" id=\"tplBtns\">\n      <button data-tpl=\"classic\">전통형<small>기존 양식(초록)</small></button>\n      <button data-tpl=\"modern\">모던형<small>깔끔한 비즈니스</small></button>\n      <button data-tpl=\"green\">조경형<small>식물 장식·미색</small></button>\n    </div>\n  </div>\n\n  <details class=\"card\" id=\"styleBox\">\n    <summary>색상 · 문구 바꾸기</summary>\n    <div class=\"grid\" style=\"margin-top:12px\">\n      <div data-for=\"classic\"><label>머리줄 색 (전통형)</label><input type=\"color\" data-st=\"classic.head\"></div>\n      <div data-for=\"classic\"><label>계·공과잡비 줄 색</label><input type=\"color\" data-st=\"classic.sum\"></div>\n      <div data-for=\"classic\"><label>합계 줄 색</label><input type=\"color\" data-st=\"classic.total\"></div>\n      <div data-for=\"modern\"><label>포인트 색 (모던형)</label><input type=\"color\" data-st=\"modern.main\"></div>\n      <div data-for=\"modern\"><label>상단 띠·합계 색</label><input type=\"color\" data-st=\"modern.dark\"></div>\n      <div data-for=\"green\"><label>포인트 색 (조경형)</label><input type=\"color\" data-st=\"green.main\"></div>\n    </div>\n    <div class=\"swatches\" id=\"swatches\"></div>\n    <div class=\"grid\" style=\"margin-top:12px\">\n      <div><label>제목</label><input data-st=\"title\"></div>\n      <div><label>영문 부제 (모던·조경형)</label><input data-st=\"sub\"></div>\n      <div><label>맺음말 (모던·조경형)</label><input data-st=\"closing\"></div>\n      <div style=\"grid-column:1/-1\"><label>하단 안내문 (예: 견적 유효기간 30일 / 자재 변동 시 금액 변동)</label><input data-st=\"note\" placeholder=\"비워두면 표시 안 함\"></div>\n    </div>\n    <div class=\"row-btns\"><button id=\"stReset\">이 양식 기본값으로</button></div>\n  </details>\n\n  <div class=\"card\">\n    <h2>저장 · 내려받기</h2>\n    <button class=\"primary save\" id=\"btnSave\">발급 리스트에 저장</button>\n    <div class=\"save-state\" id=\"saveState\"></div>\n    <div class=\"dl\">\n      <button class=\"primary\" id=\"dlJpg\">JPG</button>\n      <button class=\"primary\" id=\"dlPdf\">PDF</button>\n      <button class=\"primary\" id=\"dlXlsx\">엑셀</button>\n    </div>\n  </div>\n\n  <div class=\"preview-scroll\"><div id=\"sheet\"></div></div>\n</div>\n\n\n<script>\nconst PRESETS = [\"부대토목\",\"현관 판석\",\"계단 및 판석\",\"주차장 판석\",\"집주변 판석\",\"보도블럭\",\"화단마주석\",\"호피석\",\"화단 판석\",\"디딤돌\",\"터밭\",\"수전\",\"왕사\",\"소나무\",\"에메랄드그린\",\"라일락\",\"화수해당화\",\"박태기\",\"단풍나무\",\"회양나무\",\"미측백\",\"포크레인\",\"잔디\",\"잔디엣지\"];\nconst DEF_CO = {name:\"미래조경\",ceo:\"주용\",addr:\"경기도 여주시 능산로 13 바동 634호\",tel:\"(010)6625-4668\",fax:\"(031)886-4668\",phone:\"010-6625-4668\",bank:\"국민은행\",holder:\"주용\",account:\"200001-04-151279\",stamp:\"\"};\nconst DEFAULT_STAMP = true; // stamp.png (기본 도장)\nconst today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,\"0\")}-${String(d.getDate()).padStart(2,\"0\")}`; };\nconst newQuote = () => ({client:\"\",date:today(),title:\"\",rate:\"5\",vat:\"부가세별도\",items:[{n:\"\",s:\"\",u:\"식\",q:\"1\",p:\"\"}]});\nconst load = (k,d) => { try { const v = localStorage.getItem(k); return v ? Object.assign(d, JSON.parse(v)) : d; } catch(e){ return d; } };\nvar syncReady = false;\nconst save = (k,v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch(e){} if(syncReady && KV_MAP[k]) pushKV(KV_MAP[k], v); };\n\nlet co = load(\"jooyong-company\", {...DEF_CO});\nlet q = load(\"jooyong-quote\", newQuote());\nlet prices = load(\"jooyong-prices\", {});\n\nconst num = s => { const v = parseFloat(String(s ?? \"\").replace(/[^0-9.\\-]/g,\"\")); return isNaN(v) ? 0 : v; };\nconst fmt = n => Math.round(n).toLocaleString(\"ko-KR\");\nconst esc = s => String(s ?? \"\").replace(/[&<>\"]/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\n\nfunction korMoney(n){\n  n = Math.round(n); if(!n) return \"영\";\n  const d = [\"\",\"일\",\"이\",\"삼\",\"사\",\"오\",\"육\",\"칠\",\"팔\",\"구\"], u = [\"\",\"십\",\"백\",\"천\"], big = [\"\",\"만\",\"억\",\"조\"];\n  let out = \"\", g = 0;\n  while(n > 0){\n    const part = n % 10000; n = Math.floor(n/10000);\n    if(part){\n      let s = \"\", p = part;\n      for(let i=0;i<4;i++){ const x = p % 10; p = Math.floor(p/10); if(x) s = d[x] + u[i] + s; }\n      out = s + big[g] + out;\n    }\n    g++;\n  }\n  return out;\n}\nfunction calc(){\n  const sub = q.items.reduce((a,it)=> a + (it.blank ? 0 : num(it.q)*num(it.p)), 0);\n  const etc = Math.round(sub * num(q.rate) / 100);\n  const tot = sub + etc, sep = q.vat !== \"부가세포함\";\n  const supply = sep ? tot : Math.round(tot / 1.1), vat = sep ? Math.round(tot * 0.1) : tot - supply;\n  return {sub, etc, tot, supply, vat, grand: supply + vat, sep, show: q.vatShow ?? sep};\n}\nfunction fmtDate(s){ if(!s) return \"\"; const [y,m,d] = s.split(\"-\").map(Number); return `${y}년 ${m}월 ${d}일`; }\nfunction stampHTML(){\n  if(co.stamp) return `<img src=\"${co.stamp}\" alt=\"\">`;\n  if(DEFAULT_STAMP) return `<img src=\"/jooyong/stamp.png\" alt=\"\">`;\n  const t = esc(co.ceo || \"\").slice(0,3);\n  return `<svg viewBox=\"0 0 50 50\"><circle cx=\"25\" cy=\"25\" r=\"22\" fill=\"none\" stroke=\"#d22\" stroke-width=\"2.5\"/><text x=\"25\" y=\"${t.length>2?29:30}\" text-anchor=\"middle\" font-size=\"${t.length>2?11:14}\" font-weight=\"800\" fill=\"#d22\" font-family=\"Nanum Myeongjo,serif\">${t}</text></svg>`;\n}\n\n/* ---------- 입력 화면 ---------- */\n/* ---------- 자주 쓰는 항목 (공종명 · 규격 · 단위) ---------- */\nconst DEF_LIB = {n: PRESETS, s: [\"주차장에서 현관\",\"태두리마주석\",\"H1.5 W0.8\",\"H2.0 W1.0\",\"R10\",\"R15\",\"B8\"], u: [\"식\",\"m2\",\"m\",\"주\",\"빠렛\",\"일\",\"타\",\"개\",\"대\",\"EA\",\"㎥\",\"톤\",\"본\",\"인\"]};\nlet lib = load(\"jooyong-lib\", JSON.parse(JSON.stringify(DEF_LIB)));\nconst LIB_NAME = {n:\"공종명\", s:\"규격\", u:\"단위\"};\nfunction libAdd(f, v, front){\n  v = String(v || \"\").trim(); if(!v || !lib[f]) return;\n  const i = lib[f].indexOf(v);\n  if(i >= 0){ if(!front) return; lib[f].splice(i,1); }\n  front ? lib[f].unshift(v) : lib[f].push(v);\n  save(\"jooyong-lib\", lib);\n}\n// 초성 검색: \"ㅅㄴ\" → 소나무\nconst CHO = \"ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ\";\nconst cho = ch => { const c = ch.charCodeAt(0) - 0xAC00; return c >= 0 && c < 11172 ? CHO[Math.floor(c/588)] : ch; };\nfunction score(t, k){\n  if(!k) return 1;\n  const T = t.toLowerCase().replace(/\\s/g,\"\"), K = k.toLowerCase().replace(/\\s/g,\"\");\n  if(T.startsWith(K)) return 3;\n  if(T.includes(K)) return 2;\n  for(let s = 0; s + K.length <= T.length; s++){\n    let ok = true;\n    for(let j = 0; j < K.length && ok; j++){ const a = T[s+j], b = K[j]; ok = a === b || (CHO.includes(b) && cho(a) === b); }\n    if(ok) return s === 0 ? 2.5 : 1.5;\n  }\n  return 0;\n}\n\nconst FIELDS = [[\"n\",\"공종명\"],[\"s\",\"규격\"],[\"u\",\"단위\"],[\"q\",\"수량\"],[\"p\",\"단가\"],[\"r\",\"비고\"]];\nfunction renderItems(){\n  const box = document.getElementById(\"items\");\n  box.innerHTML = q.items.map((it,i)=> it.blank\n    ? `<div class=\"item blank\"><span class=\"nm\" style=\"grid-column:1/-2\">— 빈 줄 (구분선) —</span><button class=\"del\" data-del=\"${i}\">✕</button></div>`\n    : `<div class=\"item\">${FIELDS.map(([f,l]) => `<div class=\"fld ${f===\"n\"?\"nm\":\"\"}\" data-l=\"${l}\"><input data-i=\"${i}\" data-f=\"${f}\" placeholder=\"${l}\" autocomplete=\"off\"\n        ${f===\"q\"?'inputmode=\"decimal\"':f===\"p\"?'inputmode=\"numeric\"':\"\"} ${\"nsu\".includes(f)?'class=\"ac\"':\"\"}\n        value=\"${f===\"p\" ? (it.p ? fmt(num(it.p)) : \"\") : esc(it[f])}\"></div>`).join(\"\")}\n      <span class=\"amt\" id=\"amt${i}\">${fmt(num(it.q)*num(it.p))}</span>\n      <button class=\"del\" data-del=\"${i}\" title=\"삭제\">✕</button></div>`).join(\"\");\n}\nfunction refresh(){\n  const t = calc();\n  document.getElementById(\"tSub\").textContent = fmt(t.sub);\n  document.getElementById(\"tEtc\").textContent = fmt(t.etc);\n  document.getElementById(\"tTot\").textContent = fmt(t.tot);\n  document.getElementById(\"tVat\").textContent = fmt(t.vat);\n  document.getElementById(\"tGrand\").textContent = fmt(t.grand);\n  document.getElementById(\"vatShow\").checked = t.show;\n  document.getElementById(\"vatShowTxt\").textContent = t.sep ? \"견적서에 부가세(10%)·총 합계 표시\" : \"견적서에 공급가액·부가세 나눠서 표시\";\n  document.getElementById(\"tVatWrap\").parentElement.querySelectorAll(\"#tVatWrap, #tVatWrap + span\").forEach(s => s.style.display = t.sep && !t.show ? \"none\" : \"\");\n  q.items.forEach((it,i)=>{ const e = document.getElementById(\"amt\"+i); if(e) e.textContent = fmt(num(it.q)*num(it.p)); });\n  renderSheet(); save(\"jooyong-quote\", q); updateSaveState();\n}\nfunction setField(i, f, v){\n  const it = q.items[i]; if(!it) return;\n  it[f] = v;\n  const el = document.querySelector(`#items input[data-i=\"${i}\"][data-f=\"${f}\"]`);\n  if(el) el.value = f === \"p\" ? (num(v) ? fmt(num(v)) : \"\") : v;\n}\n// 공종명을 고르면 기억된 단위를 바로 반영 (그 뒤에 자유롭게 수정 가능), 단가·규격은 비어 있을 때만\n// 공종명에 쓴 단위를 기억 → 다음에 같은 공종명을 쓰면 자동으로 들어감\nfunction rememberUnit(i){\n  const it = q.items[i]; if(!it?.n || !it.u) return;\n  prices[it.n] = {...prices[it.n], u: it.u}; save(\"jooyong-prices\", prices);\n}\nfunction fillFromMemory(i){\n  const it = q.items[i], m = prices[it.n]; if(!m) return;\n  if(m.u && m.u !== it.u) setField(i, \"u\", m.u);\n  if(!num(it.p) && m.p) setField(i, \"p\", m.p);\n  if(m.s && !it.s) setField(i, \"s\", m.s);\n}\ndocument.getElementById(\"items\").addEventListener(\"input\", e=>{\n  const el = e.target, i = el.dataset.i; if(i === undefined) return;\n  const it = q.items[i]; it[el.dataset.f] = el.value;\n  if(el.dataset.f === \"p\"){ const v = num(el.value); el.value = v ? fmt(v) : \"\"; it.p = String(v || \"\"); }\n  if(el.classList.contains(\"ac\")) acOpen(el);\n  refresh();\n});\n// 칸을 벗어나면 입력한 값을 기억 (다음부터 자동완성)\ndocument.getElementById(\"items\").addEventListener(\"change\", e=>{\n  const el = e.target, i = el.dataset.i, f = el.dataset.f; if(i === undefined) return;\n  const it = q.items[i];\n  if(\"nsu\".includes(f)) libAdd(f, el.value);\n  if(f === \"n\") fillFromMemory(i);\n  if(f === \"u\") rememberUnit(i);\n  if(it.n && (f === \"p\" || f === \"s\") && num(it.p)){ prices[it.n] = {...prices[it.n], p:it.p, u:it.u, s:it.s}; save(\"jooyong-prices\", prices); }\n  refresh();\n});\ndocument.getElementById(\"items\").addEventListener(\"focusin\", e=>{ if(e.target.classList.contains(\"ac\")){ acOpen(e.target); if(e.target.dataset.f === \"u\") setTimeout(() => e.target.select(), 0); } });\ndocument.getElementById(\"items\").addEventListener(\"focusout\", ()=> setTimeout(()=>{ if(!document.activeElement?.classList.contains(\"ac\")) acClose(); }, 120));\n\n/* ---------- 자동완성 드롭다운 ---------- */\nconst ac = document.createElement(\"div\"); ac.id = \"ac\"; ac.hidden = true; document.body.appendChild(ac);\nlet acEl = null, acSel = -1, acList = [];\nfunction acOpen(el){\n  acEl = el; const f = el.dataset.f, k = el.value.trim();\n  const showAll = !k || lib[f].includes(k); // 비어 있거나 이미 목록에 있는 값이면 전체 목록\n  acList = lib[f].map((v,idx) => ({v, s: showAll ? (v === k ? 9 : 1) : score(v, k), idx}))\n    .filter(x => x.s > 0 && (showAll || x.v !== k)).sort((a,b) => b.s - a.s || a.idx - b.idx).slice(0, 20).map(x => x.v);\n  acSel = -1;\n  const canAdd = k && !lib[f].includes(k);\n  if(!acList.length && !canAdd){ acClose(); return; }\n  ac.innerHTML = `<div class=\"ac-h\">${LIB_NAME[f]} ${k && !showAll ? `‘${esc(k)}’ 추천` : \"자주 쓰는 목록\"}<button data-manage=\"${f}\">편집</button></div>` +\n    acList.map((v,j) => `<div class=\"ac-o${v === k ? \" cur\" : \"\"}\" data-j=\"${j}\">${esc(v)}${f === \"n\" && prices[v]?.p ? `<small>${esc(prices[v].u || \"\")} · ${fmt(num(prices[v].p))}원</small>` : \"\"}</div>`).join(\"\") +\n    (canAdd ? `<div class=\"ac-o add\" data-add=\"1\">＋ ‘${esc(k)}’ 자주 쓰는 목록에 추가</div>` : \"\");\n  const r = el.getBoundingClientRect();\n  ac.style.left = Math.max(8, Math.min(r.left, innerWidth - Math.max(r.width, 240) - 8)) + scrollX + \"px\";\n  ac.style.top = r.bottom + scrollY + 4 + \"px\";\n  ac.style.minWidth = Math.max(r.width, f === \"u\" ? 160 : 220) + \"px\";\n  ac.hidden = false;\n}\nfunction acClose(){ ac.hidden = true; acEl = null; }\nfunction acPick(v){\n  if(!acEl) return;\n  const i = acEl.dataset.i, f = acEl.dataset.f;\n  setField(i, f, v); libAdd(f, v, true);\n  if(f === \"n\") fillFromMemory(i);\n  if(f === \"u\") rememberUnit(i);\n  refresh(); acClose();\n  // 다음 칸으로 이동\n  const next = document.querySelector(`#items input[data-i=\"${i}\"][data-f=\"${({n:\"s\",s:\"u\",u:\"q\"})[f]}\"]`);\n  if(next){ next.focus(); if(next.dataset.f === \"q\") next.select(); }\n}\nac.addEventListener(\"pointerdown\", e => e.preventDefault()); // 입력칸 포커스 유지\n// 목록 바깥을 누르면 항상 닫기 (아이폰은 빈 곳을 눌러도 입력칸 포커스가 안 풀림)\n// 모바일: 빈 곳을 터치하거나 손가락으로 스크롤하면 입력 포커스 해제 (키보드 내림)\nconst FOCUSABLE = \"input,select,textarea,button,label,a,summary,#ac\";\ndocument.addEventListener(\"pointerdown\", e => {\n  if(e.pointerType !== \"touch\" || e.target.closest(FOCUSABLE)) return;\n  const a = document.activeElement;\n  if(a && a !== document.body && a.matches(\"input,select,textarea\")){ acClose(); a.blur(); }\n}, true);\nlet touchY = null;\ndocument.addEventListener(\"touchstart\", e => { touchY = e.target.closest(\"#ac\") ? null : e.touches[0].clientY; }, {passive:true});\ndocument.addEventListener(\"touchmove\", e => {\n  if(touchY === null || Math.abs(e.touches[0].clientY - touchY) < 12) return;\n  touchY = null;\n  const a = document.activeElement;\n  if(a && a.matches(\"input,select,textarea\")){ acClose(); a.blur(); } else acClose();\n}, {passive:true});\ndocument.addEventListener(\"pointerdown\", e => {\n  if(ac.hidden || ac.contains(e.target) || e.target === acEl) return;\n  acClose();\n}, true);\ndocument.getElementById(\"items\").addEventListener(\"click\", e => {\n  if(e.target.classList?.contains(\"ac\") && ac.hidden && document.activeElement === e.target) acOpen(e.target);\n});\nac.addEventListener(\"click\", e => {\n  const m = e.target.closest(\"[data-manage]\"); if(m){ acClose(); openLib(m.dataset.manage); return; }\n  const o = e.target.closest(\".ac-o\"); if(!o) return;\n  if(o.dataset.add){ const v = acEl.value.trim(); libAdd(acEl.dataset.f, v, true); toast(`‘${v}’ 추가했어요`); acPick(v); }\n  else acPick(acList[o.dataset.j]);\n});\ndocument.getElementById(\"items\").addEventListener(\"keydown\", e => {\n  if(ac.hidden || !acEl) return;\n  const opts = ac.querySelectorAll(\".ac-o\");\n  if(e.key === \"ArrowDown\" || e.key === \"ArrowUp\"){ e.preventDefault(); acSel = (acSel + (e.key === \"ArrowDown\" ? 1 : -1) + opts.length) % opts.length; opts.forEach((o,j)=>o.classList.toggle(\"on\", j === acSel)); }\n  else if(e.key === \"Enter\" && acSel >= 0){ e.preventDefault(); opts[acSel].click(); }\n  else if(e.key === \"Escape\") acClose();\n});\naddEventListener(\"resize\", () => acEl && acOpen(acEl));\n\n/* ---------- 자주 쓰는 항목 관리 ---------- */\nlet libTab = \"n\";\nfunction openLib(f){ libTab = f || libTab; const d = document.getElementById(\"libBox\"); d.open = true; renderLib(); d.scrollIntoView({behavior:\"smooth\", block:\"start\"}); }\nfunction renderLib(){\n  document.querySelectorAll(\"[data-libtab]\").forEach(b => b.classList.toggle(\"on\", b.dataset.libtab === libTab));\n  document.getElementById(\"libAdd\").placeholder = `${LIB_NAME[libTab]} 추가 (쉼표로 여러 개)`;\n  const box = document.getElementById(\"libList\");\n  box.className = libTab === \"n\" ? \"lib-rows\" : \"lib-chips\";\n  box.innerHTML = lib[libTab].length ? lib[libTab].map((v,i) => libTab === \"n\"\n    ? `<div class=\"lib-row\"><span>${esc(v)}</span><input data-lu=\"${i}\" placeholder=\"단위\" value=\"${esc(prices[v]?.u || \"\")}\"><input data-lp=\"${i}\" inputmode=\"numeric\" placeholder=\"기본 단가\" value=\"${prices[v]?.p ? fmt(num(prices[v].p)) : \"\"}\"><button class=\"del\" data-ldel=\"${i}\">✕</button></div>`\n    : `<span class=\"chip\">${esc(v)}<button data-ldel=\"${i}\">✕</button></span>`).join(\"\") : `<div class=\"empty\" style=\"padding:16px\">목록이 비어 있어요</div>`;\n}\ndocument.getElementById(\"libTabs\").onclick = e => { const b = e.target.closest(\"[data-libtab]\"); if(b){ libTab = b.dataset.libtab; renderLib(); } };\ndocument.getElementById(\"libAddBtn\").onclick = () => {\n  const el = document.getElementById(\"libAdd\");\n  el.value.split(\",\").map(s=>s.trim()).filter(Boolean).forEach(v => libAdd(libTab, v, true));\n  el.value = \"\"; renderLib(); el.focus();\n};\ndocument.getElementById(\"libAdd\").onkeydown = e => { if(e.key === \"Enter\"){ e.preventDefault(); document.getElementById(\"libAddBtn\").click(); } };\ndocument.getElementById(\"libList\").addEventListener(\"click\", e => {\n  const i = e.target.closest(\"[data-ldel]\")?.dataset.ldel; if(i === undefined) return;\n  lib[libTab].splice(i,1); save(\"jooyong-lib\", lib); renderLib();\n});\ndocument.getElementById(\"libList\").addEventListener(\"change\", e => {\n  const el = e.target, i = el.dataset.lu ?? el.dataset.lp; if(i === undefined) return;\n  const name = lib.n[i], m = prices[name] || {};\n  if(el.dataset.lu !== undefined) m.u = el.value.trim(); else { m.p = String(num(el.value) || \"\"); el.value = m.p ? fmt(num(m.p)) : \"\"; }\n  prices[name] = m; save(\"jooyong-prices\", prices);\n});\ndocument.getElementById(\"libReset\").onclick = () => { if(confirm(`${LIB_NAME[libTab]} 목록을 처음 상태로 되돌릴까요?`)){ lib[libTab] = [...DEF_LIB[libTab]]; save(\"jooyong-lib\", lib); renderLib(); } };\ndocument.getElementById(\"items\").addEventListener(\"click\", e=>{\n  const i = e.target.dataset.del; if(i === undefined) return;\n  q.items.splice(i,1); renderItems(); refresh();\n});\ndocument.getElementById(\"addItem\").onclick = ()=>{ q.items.push({n:\"\",s:\"\",u:\"식\",q:\"1\",p:\"\"}); renderItems(); refresh(); [...document.querySelectorAll('#items .nm input')].pop()?.focus(); };\ndocument.getElementById(\"addBlank\").onclick = ()=>{ q.items.push({blank:true}); renderItems(); refresh(); };\ndocument.getElementById(\"btnNew\").onclick = ()=>{\n  if(isDirty() && !confirm(\"저장하지 않은 내용이 있어요. 새로 작성할까요?\")) return;\n  openQuote(newQuote());\n};\n\nfunction bindQ(){ document.querySelectorAll(\"[data-q]\").forEach(el=>{ el.value = q[el.dataset.q] ?? \"\"; }); }\ndocument.querySelectorAll(\"[data-q]\").forEach(el=> el.addEventListener(\"input\", ()=>{ q[el.dataset.q] = el.value; refresh(); }));\n/* 회사 정보 여러 개 */\nconst coId = () => \"c\" + Date.now().toString(36) + Math.random().toString(36).slice(2,5);\nlet cos = []; try { cos = JSON.parse(localStorage.getItem(\"jooyong-companies\") || \"[]\"); } catch(e){}\nif(!co.id) co.id = coId();\nif(!cos.some(c => c.id === co.id)) cos.unshift(JSON.parse(JSON.stringify(co)));\nfunction saveCo(){\n  const i = cos.findIndex(c => c.id === co.id);\n  if(i >= 0) cos[i] = clone(co); else cos.push(clone(co));\n  save(\"jooyong-company\", co); save(\"jooyong-companies\", cos); renderCoSel();\n  const h1 = document.querySelector(\"header.top h1\"); if(h1) h1.textContent = (co.name || \"견적서\") + \" 견적\";\n}\nfunction bindCo(){\n  document.querySelectorAll(\"[data-co]\").forEach(el => { if(el !== document.activeElement) el.value = co[el.dataset.co] ?? \"\"; });\n  const h1 = document.querySelector(\"header.top h1\"); if(h1) h1.textContent = (co.name || \"견적서\") + \" 견적\";\n  renderCoSel();\n}\nfunction renderCoSel(){\n  document.getElementById(\"coSel\").innerHTML = cos.map(c => `<option value=\"${c.id}\" ${c.id === co.id ? \"selected\" : \"\"}>${esc(c.name || \"(이름 없음)\")}${c.ceo ? \" · \" + esc(c.ceo) : \"\"}</option>`).join(\"\");\n  document.getElementById(\"coNow\").textContent = co.name ? \"· \" + co.name : \"\";\n  document.getElementById(\"coDel\").disabled = cos.length < 2;\n}\nfunction useCo(id){\n  const c = cos.find(x => x.id === id); if(!c) return false;\n  co = Object.assign({...DEF_CO}, clone(c)); save(\"jooyong-company\", co); bindCo(); renderSheet(); return true;\n}\ndocument.getElementById(\"coSel\").onchange = e => { useCo(e.target.value); toast(\"회사 정보를 불러왔어요\"); };\ndocument.getElementById(\"coAdd\").onclick = () => {\n  co = {...clone(co), id: coId(), name: (co.name || \"\") + \" (복사)\"}; saveCo(); bindCo(); renderSheet();\n  const n = document.querySelector(\"[data-co=name]\"); n.focus(); n.select();\n  toast(\"새 회사 정보를 만들었어요. 내용을 고쳐주세요\");\n};\ndocument.getElementById(\"coDel\").onclick = () => {\n  if(cos.length < 2 || !confirm(`'${co.name}' 회사 정보를 삭제할까요?`)) return;\n  cos = cos.filter(c => c.id !== co.id); save(\"jooyong-companies\", cos); useCo(cos[0].id);\n};\ndocument.querySelectorAll(\"[data-co]\").forEach(el=>{ el.value = co[el.dataset.co] ?? \"\"; el.addEventListener(\"input\", ()=>{ co[el.dataset.co] = el.value; saveCo(); renderSheet(); }); });\ndocument.getElementById(\"stampFile\").onchange = e=>{\n  const f = e.target.files[0]; if(!f) return;\n  const img = new Image(), r = new FileReader();\n  r.onload = ()=>{ img.onload = ()=>{ co.stamp = processStamp(img); saveCo(); renderSheet(); }; img.src = r.result; };\n  r.readAsDataURL(f);\n};\ndocument.getElementById(\"stampClear\").onclick = ()=>{ co.stamp = \"\"; saveCo(); renderSheet(); };\n// 흰 배경을 투명하게 하고, 도장 부분만 잘라 정사각형(300px)으로 맞춤\nfunction processStamp(img, size = 300){\n  const c = document.createElement(\"canvas\"), x = c.getContext(\"2d\");\n  c.width = img.naturalWidth; c.height = img.naturalHeight; x.drawImage(img, 0, 0);\n  const d = x.getImageData(0, 0, c.width, c.height), p = d.data;\n  let x0 = c.width, y0 = c.height, x1 = 0, y1 = 0;\n  for(let i = 0; i < p.length; i += 4){\n    const mn = Math.min(p[i], p[i+1], p[i+2]);\n    const a = Math.max(0, Math.min(255, (235 - mn) * 3)); // 밝을수록 투명\n    p[i+3] = Math.min(p[i+3], a);\n    if(p[i+3] > 40){ const k = i/4, px = k % c.width, py = (k / c.width) | 0; if(px<x0)x0=px; if(px>x1)x1=px; if(py<y0)y0=py; if(py>y1)y1=py; }\n  }\n  x.putImageData(d, 0, 0);\n  if(x1 <= x0) return c.toDataURL(\"image/png\");\n  const w = x1-x0+1, h = y1-y0+1, side = Math.max(w, h), o = document.createElement(\"canvas\");\n  o.width = o.height = size;\n  const s = size / side;\n  o.getContext(\"2d\").drawImage(c, x0, y0, w, h, (size - w*s)/2, (size - h*s)/2, w*s, h*s);\n  return o.toDataURL(\"image/png\");\n}\n\n/* ---------- 견적서 양식 ---------- */\nconst MIN_ROWS = 18;\nlet tpl = \"classic\"; try { tpl = localStorage.getItem(\"jooyong-tpl\") || \"classic\"; } catch(e){}\nfunction setTpl(v){ tpl = v; try { localStorage.setItem(\"jooyong-tpl\", v); } catch(e){} document.querySelectorAll(\"[data-tpl]\").forEach(b=>b.classList.toggle(\"on\", b.dataset.tpl===v)); bindSt(); renderSheet(); if(typeof updateSaveState === \"function\") updateSaveState(); }\ndocument.getElementById(\"tplBtns\").onclick = e => { const b = e.target.closest(\"[data-tpl]\"); if(b) setTpl(b.dataset.tpl); };\nconst BRANCH = (cls) => `<svg class=\"${cls}\" viewBox=\"0 0 170 120\" fill=\"none\"><path d=\"M4 8C40 20 70 40 96 70s40 42 66 46\" stroke=\"#4f7a57\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n<g fill=\"#6f9a72\"><ellipse cx=\"30\" cy=\"12\" rx=\"12\" ry=\"5\" transform=\"rotate(25 30 12)\"/><ellipse cx=\"38\" cy=\"30\" rx=\"12\" ry=\"5\" transform=\"rotate(-35 38 30)\"/>\n<ellipse cx=\"62\" cy=\"34\" rx=\"13\" ry=\"5.5\" transform=\"rotate(40 62 34)\"/><ellipse cx=\"66\" cy=\"54\" rx=\"12\" ry=\"5\" transform=\"rotate(-30 66 54)\"/>\n<ellipse cx=\"92\" cy=\"58\" rx=\"13\" ry=\"5.5\" transform=\"rotate(50 92 58)\"/><ellipse cx=\"96\" cy=\"82\" rx=\"11\" ry=\"5\" transform=\"rotate(-20 96 82)\"/>\n<ellipse cx=\"124\" cy=\"88\" rx=\"12\" ry=\"5\" transform=\"rotate(45 124 88)\"/></g><g fill=\"#a9c4a5\"><circle cx=\"140\" cy=\"108\" r=\"3\"/><circle cx=\"150\" cy=\"104\" r=\"2.5\"/></g></svg>`;\nconst itemRows = (gap) => { let no = 0; return q.items.map(it => it.blank ? `<tr class=\"gap\"><td colspan=\"8\">${gap}</td></tr>` :\n  `<tr><td class=\"no\">${++no}</td><td><b>${esc(it.n)}</b></td><td>${esc(it.s)}</td><td class=\"c\">${esc(it.u)}</td><td class=\"n\">${it.q ? fmt(num(it.q)) : \"\"}</td><td class=\"n\">${it.p ? fmt(num(it.p)) : \"\"}</td><td class=\"n\"><b>${fmt(num(it.q)*num(it.p))}</b></td><td>${esc(it.r)}</td></tr>`).join(\"\"); };\nconst COLS = `<colgroup><col style=\"width:5%\"><col style=\"width:21%\"><col style=\"width:15%\"><col style=\"width:7%\"><col style=\"width:8%\"><col style=\"width:13%\"><col style=\"width:15%\"><col style=\"width:16%\"></colgroup>`;\nconst HEAD = `<thead><tr><th>No</th><th>공종명</th><th>규격</th><th class=\"c\">단위</th><th class=\"n\">수량</th><th class=\"n\">단가</th><th class=\"n\">금액</th><th>비고</th></tr></thead>`;\nfunction renderModern(t){\n  return `\n  <div class=\"m-band\">\n    <div><div class=\"m-co\">${esc(co.name)}</div><div class=\"m-sub\">${esc(co.addr)}<br>TEL ${esc(co.tel)} &nbsp;·&nbsp; FAX ${esc(co.fax)}</div></div>\n    <div class=\"m-doc\">${esc(st.title)}<span>${esc(st.sub)}</span></div>\n  </div><div class=\"m-accent\"></div>\n  <div class=\"m-body\">\n    <div class=\"m-cards\">\n      <div><label>받는 분</label><b>${esc(q.client)} 귀하</b></div>\n      <div><label>공사명</label><b>${esc(q.title)}</b></div>\n      <div><label>견적일</label><b>${fmtDate(q.date)}</b></div>\n      <div class=\"hl\"><label>견적 금액 · ${esc(q.vat)}</label><b>₩ ${fmt(t.tot)}</b></div>\n    </div>\n    <div class=\"m-kor\">일금 ${korMoney(t.tot)} 원정</div>\n    <table>${COLS}${HEAD}<tbody>${itemRows(\"\")}</tbody></table>\n    <div class=\"m-bottom\">\n      <div class=\"m-bank\">${co.account ? `입금계좌 &nbsp;<b>${esc(co.bank)} ${esc(co.account)}</b> (${esc(co.holder)})<br>` : \"\"}담당자 &nbsp;<b>${esc(co.ceo)}</b> · ${esc(co.phone)}</div>\n      <div class=\"m-sum\">${sumLinesHTML(t)}\n      </div>\n    </div>\n    <div class=\"m-sign\">${esc(st.closing)} &nbsp; <b>${esc(co.name)}</b> 대표 <b>${esc(co.ceo)}</b> <span class=\"stamp\">${stampHTML()}</span></div>${noteHTML()}\n  </div>`;\n}\nfunction renderGarden(t){\n  return `<div class=\"g-wrap\">\n    <div class=\"g-title\"><b>${esc(st.title)}</b><span>${esc(st.sub)}</span></div>\n    <div class=\"g-row\">\n      <div class=\"g-to\"><span class=\"who\">${esc(q.client)} 귀하</span><br><small>공사명</small>${esc(q.title)}<br><small>견적일</small>${fmtDate(q.date)}</div>\n      <div class=\"g-co\"><div class=\"nm\">${esc(co.name)}<small>대표 ${esc(co.ceo)}</small><span class=\"stamp\">${stampHTML()}</span></div>${esc(co.addr)}<br>TEL ${esc(co.tel)} · FAX ${esc(co.fax)}</div>\n    </div>\n    <div class=\"g-amt\"><span class=\"k\">일금 ${korMoney(t.tot)} 원정</span><span class=\"v\">₩ ${fmt(t.tot)}<small>(${esc(q.vat)})</small></span></div>\n    <table>${COLS}${HEAD}<tbody>${itemRows(\"\")}</tbody></table>\n    <div class=\"g-tot\">\n      <div class=\"g-bank\">${co.account ? `입금계좌 <b>${esc(co.bank)} ${esc(co.account)}</b> (${esc(co.holder)})<br>` : \"\"}담당자 <b>${esc(co.ceo)}</b> · ${esc(co.phone)}</div>\n      <div class=\"g-sum\">${sumLinesHTML(t)}\n      </div>\n    </div>\n    <div class=\"g-foot\">${esc(st.closing)}</div>${noteHTML()}\n  </div>`;\n}\n/* ---------- 색상 · 문구 ---------- */\nconst DEF_ST = {classic:{head:\"#d6ead2\",sum:\"#d9d9d9\",total:\"#bfbfbf\"}, modern:{main:\"#3f9a68\",dark:\"#24292e\"}, green:{main:\"#1f4d2e\"},\n  title:\"견적서\", sub:\"QUOTATION\", closing:\"위와 같이 견적합니다.\", note:\"\"};\nconst clone = o => JSON.parse(JSON.stringify(o));\nlet st = load(\"jooyong-style\", clone(DEF_ST));\n[\"classic\",\"modern\",\"green\"].forEach(k => st[k] = Object.assign(clone(DEF_ST[k]), st[k]));\nconst SWATCH = [\"#2f6b3a\",\"#1f4d2e\",\"#3f9a68\",\"#2b6cb0\",\"#1e3a5f\",\"#7b4b2a\",\"#8a3b3b\",\"#5b4b8a\",\"#24292e\",\"#666666\"];\nconst lighten = (hex, p) => { const n = parseInt(hex.slice(1),16), m = c => Math.round(c + (255-c)*p); return `rgb(${m(n>>16)},${m((n>>8)&255)},${m(n&255)})`; };\nconst noteHTML = () => st.note ? `<div class=\"note\">${esc(st.note)}</div>` : \"\";\nconst stGet = k => k.split(\".\").reduce((o,p)=>o?.[p], st);\nconst stSet = (k,v) => { const p = k.split(\".\"); if(p.length>1) st[p[0]][p[1]] = v; else st[k] = v; };\nfunction bindSt(){\n  document.querySelectorAll(\"[data-st]\").forEach(el => el.value = stGet(el.dataset.st) ?? \"\");\n  document.querySelectorAll(\"[data-for]\").forEach(el => el.style.display = el.dataset.for === tpl ? \"\" : \"none\");\n}\ndocument.querySelectorAll(\"[data-st]\").forEach(el => el.addEventListener(\"input\", ()=>{ stSet(el.dataset.st, el.value); save(\"jooyong-style\", st); renderSheet(); }));\ndocument.getElementById(\"swatches\").innerHTML = \"추천 색: \" + SWATCH.map(c=>`<button style=\"background:${c}\" data-c=\"${c}\" title=\"${c}\"></button>`).join(\"\");\ndocument.getElementById(\"swatches\").onclick = e => {\n  const c = e.target.dataset.c; if(!c) return;\n  if(tpl === \"classic\") st.classic.head = lighten(c, .8).replace(/rgb\\((\\d+),(\\d+),(\\d+)\\)/, (_,r,g,b)=>\"#\"+[r,g,b].map(x=>(+x).toString(16).padStart(2,\"0\")).join(\"\"));\n  else st[tpl].main = c;\n  save(\"jooyong-style\", st); bindSt(); renderSheet();\n};\ndocument.getElementById(\"stReset\").onclick = ()=>{ st[tpl] = clone(DEF_ST[tpl]); [\"title\",\"sub\",\"closing\",\"note\"].forEach(k=>st[k]=DEF_ST[k]); save(\"jooyong-style\", st); bindSt(); renderSheet(); };\nfunction applyColors(sh){\n  const s = st[tpl] || {}; sh.style.cssText = \"\";\n  Object.entries(s).forEach(([k,v]) => sh.style.setProperty(\"--\"+k, v));\n  if(s.main) sh.style.setProperty(\"--light\", lighten(s.main, .9));\n}\n\nfunction sumLinesHTML(t){\n  const L = [[\"소계\", t.sub], [`공과잡비 (${esc(q.rate)}%)`, t.etc]];\n  if(t.sep && !t.show) L.push([\"합계\", t.tot, 1]);\n  else if(t.sep) L.push([\"합계 (공급가액)\", t.tot], [\"부가세 (10%)\", t.vat], [\"총 합계 (부가세 포함)\", t.grand, 1]);\n  else { if(t.show) L.push([\"공급가액\", t.supply], [\"부가세 (10%)\", t.vat]); L.push([\"합계 (부가세 포함)\", t.grand, 1]); }\n  return L.map(([l,v,g]) => `<div${g ? ' class=\"g\"' : \"\"}><span>${l}</span><span class=\"n\">${g ? \"₩ \" : \"\"}${fmt(v)}</span></div>`).join(\"\");\n}\ndocument.querySelector(\"[data-q=vat]\").addEventListener(\"change\", () => { delete q.vatShow; refresh(); });\ndocument.getElementById(\"vatShow\").onchange = e => { q.vatShow = e.target.checked; refresh(); };\nfunction renderSheet(){\n  const t = calc(), sh = document.getElementById(\"sheet\");\n  applyColors(sh);\n  sh.className = tpl === \"classic\" ? \"\" : \"mx \" + (tpl === \"green\" ? \"garden\" : \"modern\");\n  if(tpl !== \"classic\"){ sh.innerHTML = tpl === \"green\" ? renderGarden(t) : renderModern(t); return; }\n  const rows = q.items.map(it => it.blank ? `<tr><td></td><td></td><td></td><td></td><td></td><td class=\"n\">-</td><td></td></tr>` :\n    `<tr><td>${esc(it.n)}</td><td class=\"ctr\">${esc(it.s)}</td><td class=\"ctr\">${esc(it.u)}</td><td class=\"n\">${it.q ? fmt(num(it.q)) : \"\"}</td><td class=\"n\">${it.p ? fmt(num(it.p)) : \"\"}</td><td class=\"n\">${fmt(num(it.q)*num(it.p)) || \"-\"}</td><td>${esc(it.r)}</td></tr>`);\n  while(rows.length < MIN_ROWS) rows.push(`<tr><td></td><td></td><td></td><td></td><td></td><td class=\"n\">-</td><td></td></tr>`);\n  document.getElementById(\"sheet\").innerHTML = `\n  <div class=\"ttl\">${esc(st.title)}</div>\n  <div class=\"hdr\">\n    <div class=\"client\"><span>${esc(q.client)}</span><span>귀하</span></div>\n    <div class=\"co\"><div class=\"nm\">${esc(co.name)}</div><div class=\"ad\">${esc(co.addr)}</div><div class=\"tel\">TEL:${esc(co.tel)}&nbsp; FAX:${esc(co.fax)}</div></div>\n  </div>\n  <table class=\"info\">\n    <tr><td class=\"k\">일 자</td><td class=\"c\">:</td><td>${fmtDate(q.date)}</td><td class=\"nb\" style=\"text-align:right;font-weight:400\" rowspan=\"2\">대표&nbsp;&nbsp; ${esc(co.ceo)} <span class=\"stamp\">${stampHTML()}</span></td></tr>\n    <tr><td class=\"k\">공사명</td><td class=\"c\">:</td><td>${esc(q.title)}</td></tr>\n    <tr><td class=\"k\">금 액</td><td class=\"c\">:</td><td colspan=\"2\">일금 ${korMoney(t.tot)} 원정 &nbsp;( ₩ ${fmt(t.tot)} ) <span class=\"vat\">(${esc(q.vat)})</span></td></tr>\n  </table>\n  <table class=\"it\">\n    <colgroup><col style=\"width:22%\"><col style=\"width:17%\"><col style=\"width:7%\"><col style=\"width:9%\"><col style=\"width:14%\"><col style=\"width:16%\"><col style=\"width:15%\"></colgroup>\n    <thead><tr><th rowspan=\"2\">공종명</th><th rowspan=\"2\">규 격</th><th rowspan=\"2\">단위</th><th colspan=\"3\">견 적 내 역</th><th rowspan=\"2\">비 고</th></tr>\n    <tr><th>수 량</th><th>단 가</th><th>금 액</th></tr></thead>\n    <tbody>${rows.join(\"\")}\n      <tr class=\"sum\"><td>계</td><td></td><td></td><td></td><td></td><td class=\"n\">${fmt(t.sub)}</td><td></td></tr>\n      <tr class=\"sum\"><td>공과잡비</td><td class=\"ctr\">${esc(q.rate)}%</td><td></td><td></td><td></td><td class=\"n\">${fmt(t.etc)}</td><td></td></tr>\n      ${t.sep && !t.show ? `<tr class=\"sum total\"><td>합 계</td><td></td><td></td><td></td><td></td><td class=\"n\">${fmt(t.tot)}</td><td></td></tr>` : t.sep ? `<tr class=\"sum\"><td>합 계</td><td></td><td></td><td></td><td></td><td class=\"n\">${fmt(t.tot)}</td><td></td></tr>\n      <tr class=\"sum\"><td>부가세</td><td class=\"ctr\">10%</td><td></td><td></td><td></td><td class=\"n\">${fmt(t.vat)}</td><td></td></tr>\n      <tr class=\"sum total\"><td>총 합 계</td><td class=\"ctr\">부가세 포함</td><td></td><td></td><td></td><td class=\"n\">${fmt(t.grand)}</td><td></td></tr>`\n      : `<tr class=\"sum total\"><td>합 계</td><td class=\"ctr\">부가세 포함</td><td></td><td></td><td></td><td class=\"n\">${fmt(t.tot)}</td><td></td></tr>${t.show ? `\n      <tr class=\"sum\"><td>공급가액</td><td></td><td></td><td></td><td></td><td class=\"n\">${fmt(t.supply)}</td><td></td></tr>\n      <tr class=\"sum\"><td>부가세</td><td class=\"ctr\">10%</td><td></td><td></td><td></td><td class=\"n\">${fmt(t.vat)}</td><td></td></tr>` : \"\"}`}\n      <tr class=\"sum foot\"><td>담당자</td><td class=\"ctr\" colspan=\"3\">${esc(co.ceo)}</td><td class=\"ctr\" colspan=\"3\">${esc(co.phone)}</td></tr>\n      ${co.account ? `<tr class=\"sum foot\"><td>입금계좌</td><td class=\"ctr\">${esc(co.bank)}</td><td class=\"ctr\" colspan=\"2\">${esc(co.holder)}</td><td class=\"ctr\" colspan=\"3\">${esc(co.account)}</td></tr>` : \"\"}\n    </tbody>\n  </table>${noteHTML()}`;\n}\n\n/* ---------- 내려받기 ---------- */\nconst fileBase = () => `견적서_${(q.title||q.client||\"견적\").replace(/[\\\\/:*?\"<>|\\s]+/g,\"_\")}_${q.date}`;\nfunction download(blob, name){ const a = document.createElement(\"a\"); a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(a.href), 4000); }\nasync function capture(){ await document.fonts.ready; return html2canvas(document.getElementById(\"sheet\"), {scale:2, backgroundColor:\"#fff\", windowWidth:900}); }\nasync function busy(btn, fn){ const t = btn.textContent; btn.disabled = true; btn.textContent = \"만드는 중…\"; try { await fn(); } catch(e){ alert(\"파일을 만들지 못했어요: \" + e.message); } btn.disabled = false; btn.textContent = t; }\n\ndocument.getElementById(\"dlJpg\").onclick = e => busy(e.target, async ()=>{\n  const c = await capture(); c.toBlob(b => download(b, fileBase()+\".jpg\"), \"image/jpeg\", 0.95);\n});\ndocument.getElementById(\"dlPdf\").onclick = e => busy(e.target, async ()=>{\n  const c = await capture(); const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({unit:\"mm\", format:\"a4\"}); const W = 210, H = 297, m = 8;\n  let w = W - m*2, h = c.height * w / c.width; if(h > H - m*2){ h = H - m*2; w = c.width * h / c.height; }\n  pdf.addImage(c.toDataURL(\"image/jpeg\", 0.95), \"JPEG\", (W-w)/2, m, w, h);\n  pdf.save(fileBase()+\".pdf\");\n});\ndocument.getElementById(\"dlXlsx\").onclick = e => busy(e.target, async ()=>{\n  const t = calc(), A = [];\n  A.push([st.title],[],[q.client, \"귀하\", \"\", \"\", co.name],[\"\", \"\", \"\", \"\", co.addr],[\"\", \"\", \"\", \"\", `TEL:${co.tel}  FAX:${co.fax}`],\n    [\"일    자\", \": \"+fmtDate(q.date), \"\", \"\", \"대표 \"+co.ceo],[\"공 사 명\", \": \"+q.title],\n    [\"금    액\", `: 일금 ${korMoney(t.tot)} 원정 ( ₩ ${fmt(t.tot)} ) (${q.vat})`],[],\n    [\"공종명\",\"규 격\",\"단위\",\"견 적 내 역\",\"\",\"\",\"비 고\"],[\"\",\"\",\"\",\"수 량\",\"단 가\",\"금 액\",\"\"]);\n  const first = A.length + 1;\n  q.items.forEach(it => A.push(it.blank ? [] : [it.n, it.s, it.u, num(it.q)||null, num(it.p)||null, null, it.r||\"\"]));\n  const last = A.length, subR = last + 1;\n  A.push([\"계\"],[\"공과잡비\", num(q.rate)/100],[t.sep ? \"합 계\" : \"합 계 (부가세 포함)\"]);\n  const vR = A.length + 1;\n  if(t.sep && t.show) A.push([\"부가세\", 0.1],[\"총 합 계 (부가세 포함)\"]);\n  else if(!t.sep && t.show) A.push([\"공급가액\"],[\"부가세\"]);\n  A.push([\"담당자\", co.ceo, \"\", \"\", co.phone]);\n  if(co.account) A.push([\"입금계좌\", co.bank, co.holder, \"\", co.account]);\n  const ws = XLSX.utils.aoa_to_sheet(A);\n  for(let r = first; r <= last; r++){ if(!q.items[r-first].blank) ws[\"F\"+r] = {t:\"n\", f:`IFERROR(D${r}*E${r},0)`, v:num(q.items[r-first].q)*num(q.items[r-first].p), z:\"#,##0\"}; [\"D\",\"E\"].forEach(c=>{ if(ws[c+r]) ws[c+r].z = \"#,##0\"; }); }\n  ws[\"F\"+subR] = {t:\"n\", f:`SUM(F${first}:F${last})`, v:t.sub, z:\"#,##0\"};\n  ws[\"B\"+(subR+1)] = {t:\"n\", v:num(q.rate)/100, z:\"0%\"};\n  ws[\"F\"+(subR+1)] = {t:\"n\", f:`ROUND(F${subR}*B${subR+1},0)`, v:t.etc, z:\"#,##0\"};\n  ws[\"F\"+(subR+2)] = {t:\"n\", f:`F${subR}+F${subR+1}`, v:t.tot, z:\"#,##0\"};\n  const T = subR + 2;\n  if(t.sep && t.show){ ws[\"B\"+vR] = {t:\"n\", v:0.1, z:\"0%\"}; ws[\"F\"+vR] = {t:\"n\", f:`ROUND(F${T}*B${vR},0)`, v:t.vat, z:\"#,##0\"}; ws[\"F\"+(vR+1)] = {t:\"n\", f:`F${T}+F${vR}`, v:t.grand, z:\"#,##0\"}; }\n  else if(!t.sep && t.show){ ws[\"F\"+vR] = {t:\"n\", f:`ROUND(F${T}/1.1,0)`, v:t.supply, z:\"#,##0\"}; ws[\"F\"+(vR+1)] = {t:\"n\", f:`F${T}-F${vR}`, v:t.vat, z:\"#,##0\"}; }\n  ws[\"!merges\"] = [{s:{r:0,c:0},e:{r:0,c:6}},{s:{r:9,c:3},e:{r:9,c:5}},{s:{r:9,c:0},e:{r:10,c:0}},{s:{r:9,c:1},e:{r:10,c:1}},{s:{r:9,c:2},e:{r:10,c:2}},{s:{r:9,c:6},e:{r:10,c:6}},{s:{r:7,c:1},e:{r:7,c:6}}];\n  ws[\"!cols\"] = [{wch:16},{wch:16},{wch:7},{wch:9},{wch:13},{wch:15},{wch:14}];\n  const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, \"견적서\");\n  XLSX.writeFile(wb, fileBase()+\".xlsx\");\n});\n\n/* ---------- 발급 리스트 ---------- */\n// 저장 위치: 이 기기 브라우저(localStorage). 서버 DB로 바꿀 땐 store 객체만 교체하면 됨.\nconst store = {\n  all(){ try { return JSON.parse(localStorage.getItem(\"jooyong-list\") || \"[]\"); } catch(e){ return []; } },\n  put(list){ try { localStorage.setItem(\"jooyong-list\", JSON.stringify(list)); } catch(e){ alert(\"저장 공간이 부족해요.\"); } }\n};\nconst uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2,6);\nconst snapshot = () => JSON.stringify({...q, tpl});\nlet savedSnap = null;\nconst isDirty = () => q.items.some(it => it.n || it.p) && snapshot() !== savedSnap;\n\nfunction openQuote(data){\n  q = Object.assign(newQuote(), clone(data));\n  if(data.tpl) setTpl(data.tpl);\n  if(data.coId && data.coId !== co.id && useCo(data.coId)) toast(`회사 정보: ${co.name}`);\n  savedSnap = q.id ? snapshot() : null;\n  bindQ(); renderItems(); refresh(); showEditing(); go(\"edit\");\n}\nconst dt = s => { if(!s) return \"-\"; const d = new Date(s), p = n => String(n).padStart(2,\"0\"); return `${d.getFullYear()}.${p(d.getMonth()+1)}.${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`; };\nfunction updateSaveState(){\n  const el = document.getElementById(\"saveState\"); if(!el || typeof isDirty !== \"function\") return;\n  const dirty = q.id ? isDirty() : q.items.some(it => it.n);\n  el.classList.toggle(\"dirty\", dirty);\n  el.textContent = dirty ? \"저장 안 된 변경이 있어요 — [저장]을 누르거나 내려받으면 저장돼요\" : q.updated ? `저장됨 · ${dt(q.updated)}` : \"[저장]을 누르거나 내려받으면 발급 리스트에 저장돼요\";\n}\nfunction showEditing(){\n  const e = document.getElementById(\"editing\");\n  e.classList.toggle(\"show\", !!q.id);\n  e.innerHTML = q.id ? `발급 리스트의 견적서를 수정 중: <b>${esc(q.client || \"(받는 분 없음)\")} · ${esc(q.title)}</b><br><small>작성 ${dt(q.created)} · 마지막 수정 ${dt(q.updated)} — 저장하면 덮어써요</small>` : \"\";\n  updateSaveState();\n}\nfunction saveQuote(silent){\n  const list = store.all(), t = calc(), now = new Date().toISOString();\n  if(!q.id){ q.id = uid(); q.created = now; }\n  q.updated = now;\n  const rec = {...clone(q), tpl, total:t.tot, updated:now, coId:co.id, coName:co.name};\n  const i = list.findIndex(x => x.id === q.id);\n  if(i >= 0) list[i] = rec; else list.unshift(rec);\n  store.put(list); savedSnap = snapshot(); save(\"jooyong-quote\", q); pushQuote(rec);\n  showEditing(); renderList();\n  if(!silent) toast(\"발급 리스트에 저장했어요\");\n}\nfunction toast(msg){\n  const d = document.createElement(\"div\"); d.textContent = msg;\n  d.style.cssText = \"position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#1d211c;color:#fff;padding:11px 18px;border-radius:20px;z-index:99;font-size:14px\";\n  document.body.appendChild(d); setTimeout(()=>d.remove(), 1800);\n}\ndocument.getElementById(\"btnSave\").onclick = ()=>{\n  if(!q.items.some(it=>it.n)) return alert(\"공종 내역을 하나 이상 입력해 주세요.\");\n  saveQuote();\n};\n// 내려받을 때도 자동으로 리스트에 저장\n[\"dlJpg\",\"dlPdf\",\"dlXlsx\"].forEach(id => document.getElementById(id).addEventListener(\"click\", ()=>{ if(q.items.some(it=>it.n)){ const d = !q.id || isDirty(); saveQuote(true); if(d) toast(\"발급 리스트에도 저장했어요\"); } }, true));\n\nconst TPL_NAME = {classic:\"전통형\", modern:\"모던형\", green:\"조경형\"};\nfunction renderList(){\n  const all = store.all(), kw = document.getElementById(\"search\").value.trim().toLowerCase();\n  const rows = all.filter(x => !kw || [x.client, x.title, ...x.items.map(i=>i.n)].join(\" \").toLowerCase().includes(kw));\n  document.getElementById(\"listCount\").textContent = all.length || \"\";\n  document.getElementById(\"listSum\").textContent = rows.length ? `${rows.length}건 · 합계 ₩ ${fmt(rows.reduce((a,x)=>a+(x.total||0),0))}` : \"\";\n  document.getElementById(\"list\").innerHTML = rows.length ? rows.map(x => `\n    <div class=\"qrow\">\n      <div class=\"d\">${fmtDate(x.date)}</div>\n      <div class=\"t\"><b>${esc(x.client || \"(받는 분 없음)\")} ${x.title ? \"· \" + esc(x.title) : \"\"}</b><small>${TPL_NAME[x.tpl] || \"\"} · ${x.items.filter(i=>!i.blank).length}개 항목 </small><small class=\"dates\">작성 ${dt(x.created)} · 수정 ${dt(x.updated)}</small></div>\n      <div class=\"m\">₩ ${fmt(x.total || 0)}</div>\n      <div class=\"a\"><button data-act=\"edit\" data-id=\"${x.id}\">수정</button><button data-act=\"copy\" data-id=\"${x.id}\">복제</button><button class=\"del\" data-act=\"del\" data-id=\"${x.id}\">삭제</button></div>\n    </div>`).join(\"\") : `<div class=\"empty\">${kw ? \"검색 결과가 없어요.\" : \"아직 저장된 견적서가 없어요.<br>작성 화면에서 [발급 리스트에 저장]을 눌러주세요.\"}</div>`;\n}\ndocument.getElementById(\"search\").oninput = renderList;\ndocument.getElementById(\"list\").onclick = e => {\n  const b = e.target.closest(\"[data-act]\"); if(!b) return;\n  const list = store.all(), x = list.find(r => r.id === b.dataset.id); if(!x) return;\n  if(b.dataset.act === \"edit\"){ if(isDirty() && !confirm(\"작성 중인 내용이 저장되지 않았어요. 불러올까요?\")) return; openQuote(x); }\n  if(b.dataset.act === \"copy\"){ const c = clone(x); delete c.id; delete c.created; delete c.updated; c.date = today(); openQuote(c); saveQuote(true); toast(\"복제해서 새 견적서로 등록했어요\"); }\n  if(b.dataset.act === \"del\" && confirm(`'${x.client || \"\"} ${x.title || \"\"}' 견적서를 삭제할까요?`)){\n    store.put(list.filter(r => r.id !== x.id)); pushDelete(x.id);\n    if(q.id === x.id){ delete q.id; savedSnap = null; showEditing(); }\n    renderList();\n  }\n};\nfunction go(page){\n  document.querySelectorAll(\"[data-page]\").forEach(b => b.classList.toggle(\"on\", b.dataset.page === page));\n  document.getElementById(\"pageEdit\").hidden = page !== \"edit\";\n  document.getElementById(\"pageList\").hidden = page !== \"list\";\n  if(page === \"list\"){ renderList(); pull(); }\n  window.scrollTo(0,0);\n}\ndocument.querySelector(\".tabs\").onclick = e => { const b = e.target.closest(\"[data-page]\"); if(b) go(b.dataset.page); };\ndocument.querySelector(\"header.top h1\").textContent = (co.name || \"견적서\") + \" 견적\";\n\n/* ---------- 서버 저장 (로그인 · 동기화) ---------- */\nconst API = \"/api/jooyong\";\nconst KV_MAP = {\"jooyong-company\":\"company\", \"jooyong-companies\":\"companies\", \"jooyong-lib\":\"lib\", \"jooyong-prices\":\"prices\", \"jooyong-style\":\"style\"};\nlet token = \"\"; try { token = localStorage.getItem(\"jooyong-token\") || \"\"; } catch(e){}\nconst pending = load(\"jooyong-pending\", {quotes:{}, dels:{}, kv:{}}); // 서버에 아직 못 보낸 변경\nconst savePending = () => { try { localStorage.setItem(\"jooyong-pending\", JSON.stringify(pending)); } catch(e){} };\n\nasync function api(action, data = {}){\n  const r = await fetch(API, {method:\"POST\", headers:{\"Content-Type\":\"application/json\", Authorization:\"Bearer \" + token}, body: JSON.stringify({action, ...data})});\n  const j = await r.json().catch(() => ({}));\n  if(r.status === 401 && action !== \"login\"){ showLogin(); throw new Error(\"login\"); }\n  if(!r.ok) throw new Error(j.error || \"서버 오류\");\n  return j;\n}\nfunction syncState(s){ const el = document.getElementById(\"syncState\"); if(el){ el.textContent = s; el.title = s; } }\n\n// 로컬에 저장될 때 서버에도 보냄\nconst kvTimers = {};\nfunction pushKV(key, value){\n  clearTimeout(kvTimers[key]);\n  pending.kv[key] = 1; savePending();\n  kvTimers[key] = setTimeout(async () => {\n    try { await api(\"setKV\", {key, value}); delete pending.kv[key]; savePending(); syncState(\"저장됨\"); }\n    catch(e){ syncState(\"오프라인 · 나중에 저장\"); }\n  }, 600);\n}\nasync function pushQuote(rec){\n  pending.quotes[rec.id] = 1; savePending();\n  try { await api(\"putQuote\", {quote: rec}); delete pending.quotes[rec.id]; savePending(); syncState(\"저장됨\"); }\n  catch(e){ syncState(\"오프라인 · 나중에 저장\"); }\n}\nasync function pushDelete(id){\n  delete pending.quotes[id]; pending.dels[id] = 1; savePending();\n  try { await api(\"delQuote\", {id}); delete pending.dels[id]; savePending(); syncState(\"저장됨\"); }\n  catch(e){ syncState(\"오프라인 · 나중에 저장\"); }\n}\n\n// 서버 데이터를 받아 화면에 반영 (서버가 기준, 못 보낸 변경은 다시 보냄)\nasync function pull(){\n  if(!token) return showLogin();\n  syncState(\"불러오는 중…\");\n  let data; try { data = await api(\"all\"); } catch(e){ if(e.message !== \"login\") syncState(\"오프라인\"); return; }\n  const first = !localStorage.getItem(\"jooyong-synced\");\n  const local = store.all();\n  const remote = new Map(data.quotes.map(x => [x.id, x]));\n  // 처음 연결할 때는 이 기기에만 있던 견적서도 서버로 올림\n  local.forEach(x => {\n    if(!remote.has(x.id) && (first || pending.quotes[x.id])) { remote.set(x.id, x); pushQuote(x); }\n    else if(pending.quotes[x.id]) { remote.set(x.id, x); pushQuote(x); }\n  });\n  Object.keys(pending.dels).forEach(id => { remote.delete(id); pushDelete(id); });\n  const list = [...remote.values()].sort((a,b) => String(b.updated).localeCompare(String(a.updated)));\n  try { localStorage.setItem(\"jooyong-list\", JSON.stringify(list)); } catch(e){}\n\n  const kv = data.kv || {};\n  const take = (name, lsKey, cur, apply) => {\n    if(kv[name] && !pending.kv[name]){ apply(kv[name]); try { localStorage.setItem(lsKey, JSON.stringify(kv[name])); } catch(e){} }\n    else pushKV(name, cur()); // 서버에 없거나 못 보낸 변경 → 이 기기 값 올림\n  };\n  take(\"companies\", \"jooyong-companies\", () => cos, v => { if(Array.isArray(v) && v.length) cos = v; });\n  take(\"company\", \"jooyong-company\", () => co, v => { co = Object.assign({...DEF_CO}, v); });\n  if(!cos.some(c => c.id === co.id)){ if(cos.length) co = Object.assign({...DEF_CO}, clone(cos[0])); else cos.push(clone(co)); }\n  take(\"lib\", \"jooyong-lib\", () => lib, v => { lib = Object.assign(JSON.parse(JSON.stringify(DEF_LIB)), v); });\n  take(\"prices\", \"jooyong-prices\", () => prices, v => { prices = v; });\n  take(\"style\", \"jooyong-style\", () => st, v => { st = Object.assign(clone(DEF_ST), v); [\"classic\",\"modern\",\"green\"].forEach(k => st[k] = Object.assign(clone(DEF_ST[k]), v[k])); });\n  try { localStorage.setItem(\"jooyong-synced\", \"1\"); } catch(e){}\n\n  // 화면 다시 그리기\n  bindCo();\n  if(q.id && !list.some(r => r.id === q.id)) { delete q.id; savedSnap = null; }\n  bindSt(); renderList(); renderSheet(); showEditing();\n  if(document.getElementById(\"libBox\").open) renderLib();\n  syncState(\"저장됨\");\n}\n\n/* 로그인 화면 */\nfunction showLogin(msg){\n  const box = document.getElementById(\"login\");\n  box.hidden = false; document.documentElement.classList.add(\"locked\"); acClose();\n  document.getElementById(\"loginMsg\").textContent = msg || \"\";\n  setTimeout(() => document.getElementById(\"loginPw\").focus(), 50);\n}\ndocument.getElementById(\"loginForm\").onsubmit = async e => {\n  e.preventDefault();\n  const pw = document.getElementById(\"loginPw\"), btn = e.submitter;\n  btn.disabled = true; document.getElementById(\"loginMsg\").textContent = \"\";\n  try {\n    const j = await api(\"login\", {password: pw.value});\n    token = j.token; try { localStorage.setItem(\"jooyong-token\", token); } catch(e){}\n    pw.value = \"\"; document.getElementById(\"login\").hidden = true; document.documentElement.classList.remove(\"locked\"); await pull();\n  } catch(err){ document.getElementById(\"loginMsg\").textContent = err.message; }\n  btn.disabled = false;\n};\ndocument.getElementById(\"btnLogout\").onclick = () => {\n  if(!confirm(\"로그아웃할까요? (이 기기의 저장 목록은 서버에 그대로 있어요)\")) return;\n  token = \"\"; try { localStorage.removeItem(\"jooyong-token\"); } catch(e){}\n  showLogin();\n};\n\nbindQ(); renderItems(); refresh(); setTpl(tpl);\nif(q.id && !store.all().some(r => r.id === q.id)) delete q.id; // 삭제된 견적이면 새 견적으로\nsavedSnap = q.id ? snapshot() : null;\nshowEditing(); renderList(); renderCoSel();\nsyncReady = true;\nif(token) pull(); else showLogin();\n</script>\n</body>\n</html>\n";
export default html;
